// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Restrict to valid fee rate range
        vm.assume(_feeRate > 0 && _feeRate <= 5000);

        // Fuzz the remaining initialize arguments with arbitrary valid values
        address baseToken = address(0x1);
        address nft = address(0x2);
        uint128 virtualBaseTokenReserves = 1000;
        uint128 virtualNftReserves = 1000;
        uint56 changeFee = 100;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        // Initialize the contract
        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            _feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // The reference contract stores the given _feeRate; the mutant zeroes it out
        assertTrue(c.feeRate() == _feeRate);
    }
}

